import { useEffect, useMemo, useRef, useState } from 'react'
import { Search as SearchIcon, X, TrendingUp } from 'lucide-react'
import { useCatalog } from '../lib/catalog-context'
import { trending } from '../lib/selectors'
import { SeriesCard } from '../components/SeriesCard'
import { useRoute, navigate } from '../lib/router'

const SUGGESTED = ['Solo Leveling', 'Tower of God', 'Romance', 'Action', 'True Beauty']

export default function SearchPage() {
  const route = useRoute()
  const { series: catalog, loading, source, search } = useCatalog()
  const [q, setQ] = useState(route.query.get('q') ?? '')
  const [results, setResults] = useState<Awaited<ReturnType<typeof search>>>([])
  const [searching, setSearching] = useState(false)
  const requestId = useRef(0)

  useEffect(() => {
    setQ(route.query.get('q') ?? '')
  }, [route.path, route.query])

  // Debounced live search against AniList
  useEffect(() => {
    const query = q.trim()
    if (!query) {
      setResults([])
      setSearching(false)
      return
    }
    const id = ++requestId.current
    setSearching(true)
    const timer = setTimeout(() => {
      search(query)
        .then((list) => {
          if (id === requestId.current) setResults(list)
        })
        .catch(() => {
          if (id === requestId.current) setResults([])
        })
        .finally(() => {
          if (id === requestId.current) setSearching(false)
        })
    }, 350)
    return () => clearTimeout(timer)
  }, [q, search])

  const setQuery = (value: string) => {
    setQ(value)
    navigate(`/search?q=${encodeURIComponent(value)}`, { replace: true, scroll: false })
  }

  const trendingList = useMemo(() => (loading ? [] : trending(catalog, 10)), [catalog, loading])

  return (
    <main className="mx-auto max-w-[1240px] animate-fade-up px-4 py-10 sm:px-6 lg:px-8">
      <div className="mb-8">
        <div className="eyebrow mb-2 text-accent">Search Catalog</div>
        <h1 className="text-3xl font-extrabold tracking-tight sm:text-4xl">Find your next read</h1>
        <p className="mt-2 text-ink-soft">
          {source === 'mangadex'
            ? 'Live search across the full catalog — titles, alternate names, and keywords, with readable chapters.'
            : source === 'anilist'
              ? 'Live search across the AniList manhwa database — titles, authors, and keywords.'
              : 'Search by series title, author, artist, or plot keywords.'}
        </p>
      </div>

      {/* Search field */}
      <div className="mx-auto mb-8 max-w-2xl">
        <div className="flex h-14 items-center gap-3 rounded-full border border-line-strong bg-paper px-5 shadow-sm transition-colors focus-within:border-ink">
          <SearchIcon width={19} height={19} className="text-ink-faint" />
          <input
            autoFocus
            value={q}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search series title, author, artist…"
            className="w-full bg-transparent text-base outline-none placeholder:text-ink-faint"
          />
          {q && (
            <button
              onClick={() => setQuery('')}
              className="grid h-7 w-7 place-items-center rounded-full bg-ink/5 text-ink-soft transition-colors hover:bg-ink/10"
              aria-label="Clear Search"
            >
              <X width={14} height={14} />
            </button>
          )}
        </div>
        <div className="mt-3 flex flex-wrap items-center gap-2">
          <span className="text-xs font-semibold uppercase tracking-wide text-ink-faint">Try:</span>
          {SUGGESTED.map((s) => (
            <button
              key={s}
              onClick={() => setQuery(s)}
              className="rounded-full border border-line-strong px-2.5 py-1 text-xs font-medium text-ink-soft transition-colors hover:border-ink hover:text-ink"
            >
              {s}
            </button>
          ))}
        </div>
      </div>

      {/* Results */}
      {q.trim() === '' ? (
        <div>
          <div className="rounded-[18px] border border-dashed border-line-strong bg-paper px-6 py-12 text-center text-sm text-ink-faint">
            Type in the box above to search the complete MANHWAS catalog.
          </div>
          <section className="mt-12">
            <div className="mb-5 flex items-center gap-2">
              <TrendingUp width={17} height={17} className="text-accent" />
              <h2 className="text-xl font-extrabold tracking-tight">Popular This Week</h2>
            </div>
            <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
              {trendingList.map((s) => (
                <SeriesCard key={s.id} series={s} />
              ))}
            </div>
          </section>
        </div>
      ) : searching ? (
        <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
          {Array.from({ length: 10 }).map((_, i) => (
            <div key={i}>
              <div className="aspect-[3/4] animate-pulse rounded-[14px] bg-paper-3/60" />
              <div className="mt-3 h-4 w-3/4 animate-pulse rounded bg-paper-3/60" />
              <div className="mt-2 h-3 w-1/2 animate-pulse rounded bg-paper-3/60" />
            </div>
          ))}
        </div>
      ) : results.length === 0 ? (
        <div className="rounded-[18px] border border-dashed border-line-strong bg-paper px-6 py-20 text-center">
          <SearchIcon width={30} height={30} className="mx-auto text-ink-faint" />
          <div className="mt-3 text-lg font-bold">No immediate match</div>
          <p className="mx-auto mt-2 max-w-sm text-sm text-ink-soft">
            No immediate match — try searching for another title, author, or genre keyword.
          </p>
        </div>
      ) : (
        <div>
          <div className="mb-5 text-sm text-ink-faint">
            {results.length} {results.length === 1 ? 'result' : 'results'} for{' '}
            <strong className="text-ink">“{q}”</strong>
          </div>
          <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
            {results.map((s) => (
              <SeriesCard key={s.id} series={s} />
            ))}
          </div>
        </div>
      )}
    </main>
  )
}
